def mobius(c): return c['11']-c['10']-c['01']+c['00']
z0=1.0; A={'11':(1.,2.),'10':(1.,0.),'01':(0.,2.),'00':(0.,0.)}
f=lambda z,l,r:z*z+l+r
h1={k:f(z0,*a) for k,a in A.items()}
h2={k:f(h1[k],*a) for k,a in A.items()}
carrier=h1['11']; same={k:f(carrier,*a) for k,a in A.items()}
physical={k:z0+a[0]+a[1] for k,a in A.items()}
latent={k:v*v for k,v in physical.items()}
genuine={k:z0+a[0]+a[1]+0.5*a[0]*a[1] for k,a in A.items()}
print(h1,mobius(h1)); print(h2,mobius(h2)); print(same,mobius(same)); print(physical,mobius(physical)); print(latent,mobius(latent)); print(genuine,mobius(genuine)); print(3.0+0.2,0.0*(3.0+0.2)); print(1+4*4*2*1,1+4*4*16*49)
